theorem mixedNorm_le_const_mul_of_fiber_ae {c : ℝ≥0}
    (h : ∀ᵐ y ∂ν, ∀ᵐ x ∂μ, f (x, y) ≤ c * g (x, y)) :
    mixedNorm f q r μ ν ≤ c * mixedNorm g q r μ ν

theorem isOpen_setOf_mem_plate_rotate (δ : ℝ) (a x : EuclideanSpace ℝ (Fin n))
