theorem localXRay_indicator_eq_volume_lineTimes {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) (g : Line m) :
    localXRay (E.indicator (fun _ ↦ (1 : ℝ≥0∞))) g.2 g.1 = volume (lineTimes E g)

theorem exists_finite_unitInterval_cover {K : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
