    ∃ s : Finset ℝ, ∀ z ∈ K, ∃ a ∈ s, z.2 ∈ Icc a (a + 1)

theorem support_frameXRay_subset_closedBall {f : EuclideanSpace ℝ (Fin n) → ℝ≥0∞}
    {R : ℝ} (hs : Function.support f ⊆ closedBall 0 R) (u : Rotations n) :
    Function.support (frameXRay v b f u) ⊆ closedBall 0 R

theorem exists_ratio_lt_criticalExponent {n k : ℕ}
    (h : (n : ℝ) < criticalExponent ^ (k - 1) + (k : ℝ)) :
    ∃ ρ ∈ Ioo 2 criticalExponent, (n : ℝ) < ρ ^ (k - 1) + (k : ℝ)

theorem interpolate_power_bounds {N A B : ℝ≥0∞} {q θ : ℝ}
    (hq : 0 < q) (hθ : 0 ≤ θ) (hθ1 : θ ≤ 1) (hA : N ^ q ≤ A) (hB : N ^ q ≤ B) :
    N ≤ A ^ (θ / q) * B ^ ((1 - θ) / q)

theorem isBounded_richLines {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) (hEb : IsBounded E) {Ξ : Set (EuclideanSpace ℝ (Fin m))}
    (hΞ : IsBounded Ξ) {r : ℝ} (hr : 0 < r) : IsBounded (richLines E Ξ r)

theorem measurableSet_richLines {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) {Ξ : Set (EuclideanSpace ℝ (Fin m))} (hΞ : MeasurableSet Ξ) (r : ℝ) :
    MeasurableSet (richLines E Ξ r)

theorem norm_intercept_le_of_mem_richLines {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) {Ξ : Set (EuclideanSpace ℝ (Fin m))} {R A r : ℝ}
    (hR : ∀ p ∈ E, ‖p.1‖ ≤ R) (hA : ∀ ξ ∈ Ξ, ‖ξ‖ ≤ A) (hr : 0 < r)
    {g : Line m} (hg : g ∈ richLines E Ξ r) : ‖g.1‖ ≤ R + A

theorem goodTimes_spec {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)} {N : ℝ≥0∞}
    {g : Line m} {t : ℝ} (ht : t ∈ goodTimes E N g) :
    (atHeight t g, t) ∈ E ∧ volume ((fun x ↦ (x, t)) ⁻¹' E) ≤ N

theorem half_le_volume_goodTimes {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) (hEfin : volume E ≠ ∞) {r : ℝ} (hr : 0 < r) {g : Line m}
    (hg : ENNReal.ofReal r ≤ localXRay (E.indicator (fun _ ↦ (1 : ℝ≥0∞))) g.2 g.1) :
    ENNReal.ofReal (r / 2) ≤
      volume (goodTimes E (ENNReal.ofReal (2 * (volume E).toReal / r)) g)

theorem measurableSet_goodTimes_family {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) (N : ℝ≥0∞) :
    MeasurableSet {p : Line m × ℝ | p.2 ∈ goodTimes E N p.1}

theorem volume_goodTimes_of_volume_zero {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) (hzero : volume E = 0) (g : Line m) :
    volume (goodTimes E 0 g) = volume (lineTimes E g)

theorem volume_large_slices_le {E : Set (EuclideanSpace ℝ (Fin m) × ℝ)}
    (hE : MeasurableSet E) {N : ℝ≥0∞} (hN : N ≠ 0) (hNfin : N ≠ ∞) :
    volume {t : ℝ | N < volume ((fun x ↦ (x, t)) ⁻¹' E)} ≤ volume E / N

theorem measurableSet_pairFiber (a b c : ℝ) {W : Set (PairCoordinates m)}
    (hW : MeasurableSet W) (z : EuclideanSpace ℝ (Fin m)) : MeasurableSet
      (pairFiber a b c W z)

