    (hσ : Measurable σ) : MeasurableSet {x | σ x ∈ S.select (I x)}

theorem measurableSet_separatedPairs_family {X : Type*} [MeasurableSpace X]
    {I : Set (X × ℝ)} (hI : MeasurableSet I) {r : X → ℝ} (hr : Measurable r) :
    MeasurableSet {p : X × (ℝ × ℝ) | p.2 ∈ separatedPairs {t | (p.1, t) ∈ I} (r p.1)}

theorem measurableSet_twoSliceParameters_family {X : Type*} [MeasurableSpace X]
    {I : Set (X × ℝ)} (hI : MeasurableSet I) :
    MeasurableSet {p : X × (ℝ × ℝ) | p.2 ∈ twoSliceParameters {t | (p.1, t) ∈ I}}

theorem volume_le_of_mem_twoSliceParameters {m : ℕ} {I : Set ℝ}
    (hIpos : 0 < volume I) (hIfin : volume I ≠ ∞) {p : ℝ × ℝ}
    (hp : p ∈ twoSliceParameters I) {G : Set (Line m)} (hGb : IsBounded G) :
    (volume G).toReal ≤ (100 / (volume I).toReal) ^ m *
      (sliceSize {p.1, p.2} G).toReal ^ 2

theorem corner_exponent_main_term {β : ℝ} (hβ : 1 < β) :
    let q := β / (β - 1)
    (2 * q + 3 * q ^ 2 - 2) / (q + 2 * q ^ 2 - 2) = cornerUpdate β

theorem pairDensity_le_projection (a s t : ℝ) {G : Set (Line m)}
    {W : Set (PairCoordinates m)} (hWG : W ⊆ pairFamily a G) (yz : Line m) :
    pairDensity a s t W yz ≤ pairJacobian m a s t * volume (atHeight a '' G)

theorem image_dualScalar {a b t : ℝ} (hab : a ≠ b) (hta : t ≠ a) (htb : t ≠ b)
    {S : Set ℝ} (hS : ∀ u ∈ S, u ≠ a) :
    dualScalar a b t '' S = {c | c ≠ 0 ∧ dualTime a b c t ∈ S}

theorem measurable_dualScalar {X : Type*} [MeasurableSpace X] {a b t u : X → ℝ}
