theorem measurableSet_node_inner_times_family {X : Type} [MeasurableSpace X]
    {I : Set (X × ℝ)} (hI : MeasurableSet I) {a b c : X → ℝ}
    (ha : Measurable a) (hb : Measurable b) (hc : Measurable c) (i : Fin L) :
    MeasurableSet {p : ((X × ℝ) × (Fin D → ℝ)) × ℝ |
      p.2 ∈ dualTimes {t | (p.1.1.1, t) ∈ I} (b p.1.1.1) (a p.1.1.1)
        (cornerInnerCoefficient (a p.1.1.1) (c p.1.1.1) p.1.1.2 (S.time p.1.2 i))}

theorem node_outer_ne {I : Set ℝ} (hI : MeasurableSet I) (hIunit : I ⊆ Icc 0 1)
    (hIpos : 0 < volume I) {a b c δ : ℝ} (hδ : 0 < δ)
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c δ) {u : ℝ}
    (hu : u ∈ Finset.univ.image (S.time p.2.1)) : u ≠ a ∧ u ≠ c

theorem measurable_nodeChildTriple {X : Type*} [MeasurableSpace X] {a b c : X → ℝ}
    {p : X → ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (ha : Measurable a) (hb : Measurable b) (hc : Measurable c) (hp : Measurable p)
    (ij : Fin L × Fin L) :
    Measurable (fun x ↦ S.nodeChildTriple (a x) (b x) (c x) (p x) ij)

theorem nodeChildLabels_spec {I : Set ℝ} (hI : MeasurableSet I) (hIunit : I ⊆ Icc 0 1)
    (hIpos : 0 < volume I) {a b c : ℝ}
    (hbase : ((a, b), c) ∈ separatedTriples I ((volume I).toReal / 100))
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c ((volume I).toReal / 100)) {q : ℝ × ℝ}
    (hq : q ∈ (S.nodePattern hI hIunit hIpos hbase hp).children) :
    S.time p.2.1 (S.nodeChildLabels p q).1 = q.1 ∧
      S.time (p.2.2 (S.nodeChildLabels p q).1) (S.nodeChildLabels p q).2 = q.2

theorem nodeChildTriple_nodeChildLabels {I : Set ℝ} (hI : MeasurableSet I)
    (hIunit : I ⊆ Icc 0 1) (hIpos : 0 < volume I) {a b c : ℝ}
    (hbase : ((a, b), c) ∈ separatedTriples I ((volume I).toReal / 100))
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c ((volume I).toReal / 100)) {q : ℝ × ℝ}
    (hq : q ∈ (S.nodePattern hI hIunit hIpos hbase hp).children) :
    S.nodeChildTriple a b c p (S.nodeChildLabels p q) =
      ((b, q.2), dualTime b a (cornerInnerCoefficient a c p.1 q.1) q.2)

theorem nodePattern_times_subset {I : Set ℝ} (hI : MeasurableSet I) (hIunit : I ⊆ Icc 0 1)
    (hIpos : 0 < volume I) {a b c : ℝ}
    (hbase : ((a, b), c) ∈ separatedTriples I ((volume I).toReal / 100))
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c ((volume I).toReal / 100)) :
    ∀ t ∈ (S.nodePattern hI hIunit hIpos hbase hp).times, t ∈ I

theorem node_inner_coordinates_uniform_bound {I : Set ℝ} (hI : MeasurableSet I)
    (hIunit : I ⊆ Icc 0 1) (hIpos : 0 < volume I) {a b c : ℝ}
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c ((volume I).toReal / 100)) (i : Fin L) (j : Fin D) :
    |p.2.2 i j| ≤ S.upperConstant * (100 / (volume I).toReal) ^ (8 * S.boundExponent)

theorem node_outer_coordinates_uniform_bound {I : Set ℝ} (hI : MeasurableSet I)
    (hIunit : I ⊆ Icc 0 1) (hIpos : 0 < volume I) {a b c : ℝ}
    {p : ℝ × ((Fin D → ℝ) × (Fin L → Fin D → ℝ))}
    (hp : p ∈ S.cornerNodeParameters I a b c ((volume I).toReal / 100)) (j : Fin D) :
    |p.2.1 j| ≤ S.upperConstant * (100 / (volume I).toReal) ^ (8 * S.boundExponent)

theorem volume_parallelFiber_smul {r : ℝ} (hr : 0 < r) (G : Set (Line m))
    (ξ : EuclideanSpace ℝ (Fin m)) :
    volume {x | (x, ξ) ∈ r • G} = ENNReal.ofReal (r ^ m) * volume {x | (x, r⁻¹ • ξ) ∈ G}

theorem nodePattern_times_subset_treeTimes {I : Set ℝ} (hI : MeasurableSet I)
    (hIunit : I ⊆ Icc 0 1) (hIpos : 0 < volume I) (J : ℕ) {q : (ℝ × ℝ) × ℝ}
    (hq : q ∈ separatedTriples I ((volume I).toReal / 100))
    {σ : TreeCoordinate D L (J + 1) → ℝ}
    (hσ : σ ∈ S.treeParameters I (J + 1) q) :
    (S.nodePattern hI hIunit hIpos hq hσ.1).times ⊆ S.treeTimes (J + 1) q σ

theorem times_subset (T : CornerTree m β J) {I : Set ℝ}
    (ha : ∀ v, T.a v ∈ I) (hb : ∀ v, T.b v ∈ I) (hc : ∀ v, T.c v ∈ I)
    (hP : ∀ v h, ∀ t ∈ (T.pattern v h).times, t ∈ I) : ∀ t ∈ T.times, t ∈ I

theorem measurable_codeSliceMass (a b c : ℝ) {W : Set (PairCoordinates m)}
    (hW : MeasurableSet W) (z : EuclideanSpace ℝ (Fin m)) : Measurable
      (codeSliceMass a b c W z)

theorem lintegral_le_mul_measure_of_ae_le {X : Type*} [MeasurableSpace X] {μ : Measure X}
    {f : X → ℝ≥0∞} {S : Set X} (hS : Function.support f ⊆ S) {C : ℝ≥0∞}
    (hC : ∀ᵐ x ∂μ, f x ≤ C) : (∫⁻ x, f x ∂μ) ≤ C * μ S
